import {
  Bar,
  BigNumber,
  ChartHeader,
  ChartWrapper,
  ComparisonLine,
  NoDataYet,
} from 'components';
import { getConnectorData } from 'components/Chart/utils';
import { useMediaQuery } from 'hooks';

import { getBigNumberSize } from '../utils/getBigNumberSize';
import {
  StyledChartContainer,
  StyledNoticeMessageContainer,
  StyledSustainableGrowthOverviewCardContent,
} from './SustainableGrowthOverviewCard.styles';
import type { SustainableGrowthOverviewCardProps } from './types';
import {
  DEFAULT_CHART_COLORS,
  getBarChartDatasetsWithColors,
  getNegativeBarChartOptions,
} from './utils';

export const SustainableGrowthOverviewCard = ({
  data,
  tooltip,
  onClick,
  isExportPage = false,
  chartColors = DEFAULT_CHART_COLORS,
}: SustainableGrowthOverviewCardProps) => {
  const isDesktopLarge = useMediaQuery('(min-width: 1440px)');
  const isDesktopXLarge = useMediaQuery('(min-width: 1920px)');
  const hasCharts = data?.barChart || data?.comparisonLine;

  const barNegativeOptions = getNegativeBarChartOptions(data?.barChart);

  if (!data || data?.noticeMessage) {
    return (
      <ChartWrapper onClick={onClick}>
        <StyledSustainableGrowthOverviewCardContent isExportPage={isExportPage}>
          <StyledNoticeMessageContainer>
            <ChartHeader
              title={data?.chartHeader.title}
              measure={data?.chartHeader.measure}
              config={{
                inline: 'horizontal',
                type: isDesktopLarge ? 'large' : 'small',
                alignment: 'left',
              }}
            />
            <StyledChartContainer hasNoticeMessage isExportPage={isExportPage}>
              <NoDataYet
                description={data?.noticeMessage}
                size="auto"
                illustration="noDataAvailable"
              />
            </StyledChartContainer>
          </StyledNoticeMessageContainer>
        </StyledSustainableGrowthOverviewCardContent>
      </ChartWrapper>
    );
  }

  return (
    <ChartWrapper onClick={onClick}>
      <StyledSustainableGrowthOverviewCardContent isExportPage={isExportPage}>
        <BigNumber
          header={
            <ChartHeader
              title={data?.chartHeader.title}
              measure={data?.chartHeader.measure}
              period={data?.chartHeader.period}
              info={tooltip}
              config={{
                inline: 'horizontal',
                type: isDesktopLarge ? 'large' : 'small',
                alignment: 'left',
              }}
            />
          }
          data={data?.bigNumberData || []}
          size={getBigNumberSize(isDesktopXLarge, isDesktopLarge, isExportPage)}
          enableTruncation
        />

        {hasCharts && (
          <div style={{ paddingBottom: `16px` }}>
            <StyledChartContainer
              hasNoticeMessage={!!data?.noticeMessage}
              isExportPage={isExportPage}
            >
              {data?.barChart && (
                <Bar
                  size={isDesktopXLarge ? 'small' : 'xsmall'}
                  maxSize="none"
                  alwaysShowDataLabels
                  stripedIndexes={data.barChart.stripedIndexes}
                  highlightLabels={data.barChart.highlightLabels}
                  labels={data.barChart.labels ?? []}
                  datasets={getBarChartDatasetsWithColors(
                    data.barChart,
                    chartColors,
                  )}
                  formattedData={data.barChart.formattedData}
                  connector={getConnectorData(data?.barChart)}
                  axisType="none"
                  showGrid={false}
                  options={barNegativeOptions}
                />
              )}
            </StyledChartContainer>
            {data?.comparisonLine && (
              <ComparisonLine
                data={data?.comparisonLine.data}
                gridColumnsLength={
                  data?.barChart?.labels?.length ||
                  data?.comparisonLine.data?.[0]?.data?.length
                }
                gridConfig={{ paddingLeft: 8, paddingRight: 8 }}
                borderConfig={{ marginLeft: 8, marginRight: 8 }}
              />
            )}
          </div>
        )}
      </StyledSustainableGrowthOverviewCardContent>
    </ChartWrapper>
  );
};
